def _on_poll_tick(self) -> None:
    if not self.isVisible():
        return
    folder = _session_folder(self)
    if folder is None:
        return

    finished = self.controller.poll_jobs()
    for job in finished:
        if job.id != self._prep_job_id:
            continue
        self._poll.stop()
        if job.status == "completed":
            self._handle_prep_finished(folder)
        elif job.status == "aborted":
            pass
        else:
            self._handle_prep_failed(folder, job.message)
        return

    self._refresh_ui(folder)

def _handle_prep_finished(self, folder: Path) -> None:
    try:
        state = self.controller.load_session_state(folder)
    except Exception:
        state = {}
    if state.get("resume_at") == "14_done":
        self.navigate.emit("F5")
        return

    progress = self.controller.read_prep_progress(folder)
    if progress.prep_complete:
        if progress.resume_at == "10a_sync_offset_approval":
            self.navigate.emit("F2a")
        else:
            self.navigate.emit("F2")
        return
    if progress.failure:
        self._handle_prep_failed(folder, progress.failure.get("summary", "Prep failed."))
        return
    self._current.setText("Prep finished.")
    self._detail.setText("Waiting for session state to update…")
    self._retry.show()

def _prep_failure_summary(self, folder: Path, failure: dict | None, fallback: str) -> str:
    if not failure:
        return fallback
    try:
        state = self.controller.load_session_state(folder)
    except Exception:
        state = None
    return (
        failure_summary(failure, state=state, working_folder=folder)
        or fallback
    )

def _handle_prep_failed(self, folder: Path, message: str) -> None:
    progress = self.controller.read_prep_progress(folder)
    fallback = message or "Prep failed."
    summary = self._prep_failure_summary(folder, progress.failure, fallback)
    file_detail = progress.failure.get("error_detail") if progress.failure else None
    navigate_to_failure(
        self,
        summary=summary,
        retry_screen="E1",
        detail=file_detail if isinstance(file_detail, str) else None,
    )

def _refresh_ui(self, folder: Path) -> None:
    progress = self.controller.read_prep_progress(
        folder,
        fallback_started_at=self._local_started,
    )
    if progress.current_step and progress.current_step != self._local_step:
        self._local_step = progress.current_step
        self._local_started = datetime.now().astimezone()
        progress = self.controller.read_prep_progress(
            folder,
            fallback_started_at=self._local_started,
        )

    self._current.setText(progress.current_label)
    self._steps.setText("\n".join(progress.step_lines))
    timing_parts: list[str] = []
    if progress.step_started_display:
        timing_parts.append(f"Started {progress.step_started_display}")
    if progress.step_eta_display:
        timing_parts.append(progress.step_eta_display)
    timing_text = " · ".join(timing_parts)
    self._timing.setText(timing_text)
    self._timing.setVisible(bool(timing_text))

    if progress.failure and not progress.prep_complete:
        if self._prep_job_id is not None:
            job = self.controller.get_job(self._prep_job_id)
            if job is not None and job.status == "running":
                return
        summary = self._prep_failure_summary(folder, progress.failure, "Prep failed.")
        if summary:
            self._poll.stop()
            navigate_to_failure(
                self,
                summary=summary,
                retry_screen="E1",
                detail=progress.failure.get("error_detail")
                if isinstance(progress.failure.get("error_detail"), str)
                else None,
            )
            return

    if progress.prep_complete:
        self._poll.stop()
        if progress.resume_at == "10a_sync_offset_approval":
            self.navigate.emit("F2a")
        else:
            self.navigate.emit("F2")
        return

"""Fast Preview controller helpers."""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

from app.controller.paths import REPO_ROOT, SCRIPTS_DIR, ensure_scripts_path


def fast_preview_eligible_for_state(state: dict) -> bool:
    ensure_scripts_path()
    from piab_fast_preview_lib import fast_preview_eligible

    raw = Path(str((state.get("paths") or {}).get("raw") or ""))
    if not raw.is_dir():
        return False
    try:
        return fast_preview_eligible(raw)
    except FileNotFoundError:
        return False


def fast_preview_review_pending(state: dict) -> bool:
    if state.get("fast_preview_approval", {}).get("approved_at"):
        return False
    if state.get("resume_at") in ("10a_sync_offset_approval", "11_one_min_approval"):
        step = (state.get("steps") or {}).get("10p_fast_preview_one_min") or {}
        if step.get("status") == "completed":
            return True
        if (state.get("fast_preview") or {}).get("enabled"):
            return True
    return False


def full_after_preview_pending(state: dict) -> bool:
    approval = state.get("fast_preview_approval") or {}
    if not approval.get("approved_at"):
        return False
    resume_at = state.get("resume_at")
    if resume_at in ("13_full_prep_after_preview", "13_full_render"):
        return True
    render_step = (state.get("steps") or {}).get("13_full_render") or {}
    return render_step.get("status") != "completed"


def should_start_fast_preview(state: dict) -> bool:
    if state.get("fast_preview_approval", {}).get("approved_at"):
        return False
    if (state.get("steps") or {}).get("10p_fast_preview_one_min", {}).get("status") == "completed":
        return False
    return fast_preview_eligible_for_state(state)


def _run_script(script: Path, argv: list[str]) -> None:
    proc = subprocess.run(
        [sys.executable, str(script), *argv],
        cwd=str(REPO_ROOT),
        capture_output=True,
        text=True,
    )
    if proc.returncode != 0:
        detail = (proc.stderr or proc.stdout or "").strip()
        raise RuntimeError(
            f"{script.name} failed (code {proc.returncode})"
            + (f":\n{detail}" if detail else "")
        )


def approve_fast_preview(working_folder: Path) -> dict:
    folder = working_folder.resolve()
    _run_script(SCRIPTS_DIR / "piab_approve_fast_preview.py", [str(folder)])
    ensure_scripts_path()
    from piab_lib import load_piab_state

    return load_piab_state(folder)


def clear_preview_for_relabel(working_folder: Path) -> dict:
    folder = working_folder.resolve()
    ensure_scripts_path()
    from piab_fast_preview_lib import clear_preview_sandbox
    from piab_lib import load_piab_state, save_piab_state

    state = load_piab_state(folder)
    clear_preview_sandbox(state, folder)
    save_piab_state(folder, state)
    return state

